-- ============================================
-- LUMA — Thème 2 : scénario MOYEN 3/3 x4 — Proposer un deuxième rendez-vous
-- ============================================


update scenarios set content = '{"characters": {"alex": "Alex"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alex", "text": "Well, it''s getting late. I should probably head home soon.", "text_fr": "Bon, il commence à se faire tard. Je devrais sûrement rentrer bientôt.", "choices": [{"text": "Yeah, same. But I had a really great time tonight.", "text_fr": "Ouais, pareil. Mais j''ai passé un super moment ce soir.", "next": "n2"}, {"text": "Already? Time really flew by, huh?", "text_fr": "Déjà ? Le temps a vraiment filé, hein ?", "next": "n2b"}]}, "n2": {"speaker": "alex", "text": "Me too, honestly. This was way better than I expected.", "text_fr": "Moi aussi, honnêtement. C''était bien mieux que ce à quoi je m''attendais.", "choices": [{"text": "Same here! I wasn''t sure what to expect either.", "text_fr": "Pareil pour moi ! J''étais pas sûr non plus à quoi m''attendre.", "next": "n3"}]}, "n2b": {"speaker": "alex", "text": "It really did. I guess that''s a good sign, right?", "text_fr": "C''est vrai. Je suppose que c''est bon signe, non ?", "choices": [{"text": "Definitely a good sign, in my opinion.", "text_fr": "Définitivement bon signe, à mon avis.", "next": "n3"}]}, "n3": {"speaker": "alex", "text": "So... I was thinking, would you want to do this again sometime?", "text_fr": "Donc... je me disais, tu voudrais refaire ça une prochaine fois ?", "choices": [{"text": "Absolutely, I''d love that.", "text_fr": "Absolument, j''adorerais.", "next": "n4"}, {"text": "I''d like that, but can I think about the timing?", "text_fr": "J''aimerais bien, mais je peux réfléchir au timing ?", "next": "n4b"}, {"text": "(hesitate, unsure if there was real chemistry)", "text_fr": "(hésite, pas sûr(e) qu''il y ait eu une vraie alchimie)", "next": "n4c"}]}, "n4": {"speaker": "alex", "text": "Great! What are you into — dinner, something more active?", "text_fr": "Super ! T''aimes quoi — dîner, quelque chose de plus actif ?", "choices": [{"text": "How about that hiking trail you mentioned?", "text_fr": "Et si on faisait ce sentier de randonnée dont tu parlais ?", "next": "n5"}, {"text": "Dinner sounds perfect, honestly.", "text_fr": "Un dîner ça a l''air parfait, honnêtement.", "next": "n5b"}]}, "n4b": {"speaker": "alex", "text": "Of course, no pressure at all! Just let me know whenever.", "text_fr": "Bien sûr, aucune pression ! Fais-moi juste signe quand tu veux.", "choices": [{"text": "I''ll text you in a couple days, promise.", "text_fr": "Je t''écris dans quelques jours, promis.", "next": "n6"}]}, "n4c": {"speaker": "alex", "text": "(Notices the hesitation) It''s totally fine if you''re not sure — no pressure.", "text_fr": "(Remarque l''hésitation) C''est totalement ok si t''es pas sûr(e) — aucune pression.", "choices": [{"text": "It''s not that, I just want to be honest about needing time.", "text_fr": "C''est pas ça, je veux juste être honnête sur le fait d''avoir besoin de temps.", "next": "n6"}, {"text": "Actually, you know what — let''s do it, I''d like to try again.", "text_fr": "En fait, tu sais quoi — allons-y, j''aimerais réessayer.", "next": "n4"}]}, "n5": {"speaker": "alex", "text": "I love that idea! Saturday morning, maybe with coffee after?", "text_fr": "J''adore cette idée ! Samedi matin, avec un café après peut-être ?", "choices": [{"text": "Perfect, it''s a plan!", "text_fr": "Parfait, c''est prévu !", "next": "end_active"}]}, "n5b": {"speaker": "alex", "text": "Perfect, I know a great Italian place downtown.", "text_fr": "Parfait, je connais un super italien en centre-ville.", "choices": [{"text": "Sounds amazing, I can''t wait.", "text_fr": "Ça a l''air génial, j''ai hâte.", "next": "end_dinner"}]}, "n6": {"speaker": "alex", "text": "Take all the time you need, really. I enjoyed tonight either way.", "text_fr": "Prends tout le temps qu''il te faut, vraiment. J''ai apprécié ce soir de toute façon.", "choices": [{"text": "That means a lot, thank you for understanding.", "text_fr": "Ça compte beaucoup, merci de comprendre.", "next": "end_open"}]}, "end_active": {"speaker": "alex", "text": "Can''t wait! This is going to be fun.", "text_fr": "J''ai hâte ! Ça va être fun.", "end": true, "ending_label": "Deuxième rendez-vous actif prévu 🥾💕"}, "end_dinner": {"speaker": "alex", "text": "Me too, I''ll book a table for Friday!", "text_fr": "Moi aussi, je réserve une table pour vendredi !", "end": true, "ending_label": "Un dîner romantique en perspective 🍝💕"}, "end_open": {"speaker": "alex", "text": "Whenever you''re ready, I''ll be here. No rush at all.", "text_fr": "Quand tu seras prêt(e), je serai là. Aucune urgence.", "end": true, "ending_label": "Une porte laissée ouverte, en toute honnêteté 🚪"}}}'::jsonb, is_playable = true
where title = 'Proposer un deuxième rendez-vous'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
